import{_ as t,o,c as n,ae as r}from"./chunks/framework.Dn6zxbF8.js";const v=JSON.parse('{"title":"direnv","description":"","frontmatter":{"name":"direnv","quadrant":"tools","history":[{"edition":"2026.2","ring":"hold"}],"tags":["developer-experience","environment","toolchain"]},"headers":[],"relativePath":"radar/items/direnv.md","filePath":"radar/items/direnv.md"}'),a={name:"radar/items/direnv.md"};function i(s,e,d,c,h,l){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="direnv" tabindex="-1">direnv <a class="header-anchor" href="#direnv" aria-label="Permalink to &quot;direnv&quot;">​</a></h1><p>direnv loads and unloads environment variables as you move in and out of a directory, driven by a <code>.envrc</code> that lives next to the code. It carried our repositories for years, and the instinct behind it was the right one: entering a project should be a <code>cd</code>, not a checklist. <a href="./mise.html">mise</a> kept that instinct.</p><p>It is on Hold because in direnv the shell script is the interface. Everything is a program, so what began as a few exports grows toolchain activation, a PATH prepend, a decryption call, and a branch for the one machine where something is installed elsewhere. Reviewing that file means reading a program, and the version drift it hides is exactly what the file was supposed to prevent.</p><p>mise is not more restrictive here, and the case for it is not that it forbids shell. It sources shell too: <code>_.source</code> in <code>[env]</code> runs a bash script and takes what it exports, and <code>[hooks.enter]</code> runs shell in the current shell on entering a project. The difference is which one is the default. Environment, toolchain versions, tasks, and <a href="./sops.html">SOPS</a>-decrypted secrets are declarations first, read the same way by <code>mise run</code> and by CI, with shell reserved for the cases that genuinely need it. The declared <code>[env]</code> also unwinds on the way out, which hook shell does not, so the escape hatch stays the narrower tool rather than the usual one.</p><p>Hold is not a removal order, but it is not a gradual migration either. mise&#39;s own guidance is to not run the two together, since both bind environment to a directory and collide over <code>PATH</code>; there is no import of an existing <code>.envrc</code>, and the <code>mise direnv activate</code> bridge that once allowed coexistence is deprecated. A repository with a working <code>.envrc</code> is not an emergency and can keep it until someone converts it in one move. New repositories should declare the environment in mise and skip the <code>.envrc</code>.</p>',5)])])}const m=t(a,[["render",i]]);export{v as __pageData,m as default};
